/* =========================================================================
 * 【手机本地生图 v7.6】 + 【流式提示词润色引擎】
 *
 * 状态: Phase 2.9
 * 新增: 🥕 LoRA 热插拔（仅萝卜梦适配可用，TurnipDream ≥ 3.1.37 + Swap 模型）
 * 新增: 环形菜单美化 / 进入聊天自动渲染图片 / 画廊完整显示 / 图片下载按钮
 * 修复: 第一组提示词润色被思维链孤立标签污染的遗留问题
 * 修复: 出图 SSE 的 error 事件被内层 catch 吞掉，导致报错只剩「未返回完整数据」
 * ========================================================================= */

(async function () {
    'use strict';
    const hostWindow = window.parent;

    // ==========================================
    // ⚙️ 模块 1：基础依赖与配置
    // ==========================================
    const DB_NAME = "LocalDream_DB", STORE_NAME = "images";
    const DEFAULT_CONFIG = {
        resolution: 512,
        resolution_mode: "size",
        aspect_ratio: "1:1",
        custom_resolution: "",
        scheduler_base: "dpm_sde", use_karras: true,
        steps: 20, cfg: 7.0, denoise_strength: 60, seed: "",
        negative_prompt: "low quality, bad anatomy, ugly, deformed, distorted, blurry, noisy, artifacts, lowres, watermark",
        theme: "dark", fab_enabled: false, gallery_view: "grid", auto_clear: false, keep_floors: 10,
        default_tab: "config", enable_polish: false,
        // 🥕 LoRA 热插拔：lora_selection 形如 "a.safetensors@1, b.safetensors@0.7"，与 app 的 lora_selection.txt 同格式
        lora_enabled: false, lora_selection: ""
    };

    function getConfig() { const conf = localStorage.getItem("LD_Config"); return conf ? { ...DEFAULT_CONFIG, ...JSON.parse(conf) } : DEFAULT_CONFIG; }
    function saveConfig(updates) { const conf = { ...getConfig(), ...updates }; localStorage.setItem("LD_Config", JSON.stringify(conf)); return conf; }

    function getPresets() { const p = localStorage.getItem("LD_Presets"); return p ? JSON.parse(p) : {}; }
    function savePresets(pObj) { localStorage.setItem("LD_Presets", JSON.stringify(pObj)); }
    function hashPrompt(str) { let hash = 0; for (let i = 0; i < str.length; i++) hash = ((hash << 5) - hash) + str.charCodeAt(i) | 0; return 'ld_' + Math.abs(hash).toString(16); }

    /**
     * 栈配对反向匹配 <local_img> ... </local_img>
     */
    function matchAllLocalImg(content) {
        if (!content) return [];
        const OPEN = '<local_img>';
        const CLOSE = '</local_img>';
        const tags = [];
        let i = 0;
        while (i < content.length) {
            const nextOpen = content.indexOf(OPEN, i);
            const nextClose = content.indexOf(CLOSE, i);
            if (nextOpen === -1 && nextClose === -1) break;
            if (nextOpen !== -1 && (nextClose === -1 || nextOpen < nextClose)) {
                tags.push({ type: 'open', pos: nextOpen });
                i = nextOpen + OPEN.length;
            } else {
                tags.push({ type: 'close', pos: nextClose });
                i = nextClose + CLOSE.length;
            }
        }
        const openStack = [];
        const pairs = [];
        for (const tag of tags) {
            if (tag.type === 'open') {
                openStack.push(tag.pos);
            } else {
                if (openStack.length > 0) {
                    const openPos = openStack.pop();
                    pairs.push({
                        start: openPos,
                        end: tag.pos + CLOSE.length,
                        inner: content.slice(openPos + OPEN.length, tag.pos)
                    });
                }
            }
        }
        pairs.sort((a, b) => a.start - b.start);
        return pairs;
    }

    let isApiOnline = false, isProcessing = false, manualProgressCallback = null;
    setInterval(async () => {
        if (isProcessing) return;
        try {
            const controller = new AbortController(); setTimeout(() => controller.abort(), 2000);
            await fetch('http://127.0.0.1:8081/', { signal: controller.signal }); isApiOnline = true;
        } catch (e) { isApiOnline = false; }
        const dot = hostWindow.document.getElementById('ld-ui-dot'); if (dot) dot.style.background = isApiOnline ? '#22c55e' : '#64748b';
    }, 5000);

    const BlobUrlCache = {};
    const dbPromise = new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME);
        request.onupgradeneeded = (e) => { const db = e.target.result; if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME, { keyPath: 'hash' }); };
        request.onsuccess = (e) => { const db = e.target.result; if (db.objectStoreNames.contains(STORE_NAME)) resolve(db); else { const upgradeReq = indexedDB.open(DB_NAME, db.version + 1); upgradeReq.onupgradeneeded = (e2) => { const upgradeDb = e2.target.result; if (!upgradeDb.objectStoreNames.contains(STORE_NAME)) upgradeDb.createObjectStore(STORE_NAME, { keyPath: 'hash' }); }; upgradeReq.onsuccess = (e2) => resolve(e2.target.result); upgradeReq.onerror = () => reject(upgradeReq.error); } };
        request.onerror = () => reject(request.error);
    });

    async function saveImageToDB(hash, blob, prompt, config, msgId, actualSeed, genTimeMs) {
        const db = await dbPromise; return new Promise((res, rej) => { const tx = db.transaction(STORE_NAME, 'readwrite'); const data = { hash, blob, prompt, config, timestamp: Date.now(), message_id: msgId, seed: actualSeed, generation_time_ms: genTimeMs }; const req = tx.objectStore(STORE_NAME).put(data); req.onsuccess = () => res(); req.onerror = () => rej(req.error); });
    }
    async function getImageFromDB(hash) { const db = await dbPromise; return new Promise((res, rej) => { if (!db.objectStoreNames.contains(STORE_NAME)) return res(null); const req = db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).get(hash); req.onsuccess = () => res(req.result ? req.result.blob : null); req.onerror = () => rej(req.error); }); }
    async function getRecordFromDB(hash) { const db = await dbPromise; return new Promise((res, rej) => { if (!db.objectStoreNames.contains(STORE_NAME)) return res(null); const req = db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).get(hash); req.onsuccess = () => res(req.result || null); req.onerror = () => rej(req.error); }); }
    async function getAllImagesFromDB() { const db = await dbPromise; return new Promise((res, rej) => { if (!db.objectStoreNames.contains(STORE_NAME)) return res([]); const req = db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).getAll(); req.onsuccess = () => res(req.result || []); req.onerror = () => rej(req.error); }); }
    async function deleteImageFromDB(hash) { const db = await dbPromise; return new Promise((res, rej) => { const req = db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).delete(hash); req.onsuccess = () => res(); req.onerror = () => rej(req.error); }); }
    async function getBlobUrl(hash) { if (BlobUrlCache[hash]) return BlobUrlCache[hash]; const blob = await getImageFromDB(hash); if (blob) { const url = hostWindow.URL.createObjectURL(blob); BlobUrlCache[hash] = url; return url; } return null; }

    let trackers = {}; let zIndexCounter = 20000;
    function getOverlayLayer() {
        const chatContainer = hostWindow.document.getElementById('chat'); if (!chatContainer) return null;
        let layer = hostWindow.document.getElementById('ld-phantom-layer');
        if (!layer) { if (hostWindow.getComputedStyle(chatContainer).position === 'static') chatContainer.style.position = 'relative'; layer = hostWindow.document.createElement('div'); layer.id = 'ld-phantom-layer'; layer.style.cssText = `position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 99999;`; chatContainer.appendChild(layer); }
        return { layer, chatContainer };
    }
    function fastFindTextRect($container, targetText) {
        if (!$container || $container.length === 0 || !targetText) return null;
        const walker = hostWindow.document.createTreeWalker($container[0], NodeFilter.SHOW_TEXT, null, false); let node;
        while ((node = walker.nextNode())) { const idx = node.nodeValue.indexOf(targetText); if (idx !== -1) { const range = hostWindow.document.createRange(); range.setStart(node, idx); range.setEnd(node, idx + targetText.length); return range.getBoundingClientRect(); } } return null;
    }
    function transformFloaterToImage(tracker, imgUrl) {
        tracker.elem.innerHTML = `<img src="${imgUrl}" draggable="false" style="width:100%; border-radius:12px; display:block; object-fit:contain; box-shadow: 0 4px 15px rgba(0,0,0,0.1);" />`; tracker.elem.style.padding = '0px'; tracker.elem.style.border = 'none'; tracker.elem.style.background = 'transparent'; tracker.elem.style.boxShadow = 'none'; tracker.elem.style.pointerEvents = 'none';
    }
    function createPhantomFloater(hash, prompt, msgId) {
        const { layer } = getOverlayLayer(); if (!layer) return null; const panel = hostWindow.document.createElement('div'); panel.id = `ld-inst-${hash}`;
        panel.style.cssText = `position: absolute !important; width: 90% !important; max-width: 360px !important; background: rgba(128, 128, 128, 0.1) !important; backdrop-filter: blur(2px) !important; border: none !important; z-index: ${zIndexCounter} !important; padding: 10px !important; border-radius: 8px !important; font-family: system-ui, sans-serif !important; display: flex !important; flex-direction: column !important; color: #94a3b8 !important; pointer-events: none !important; opacity: 0; transition: opacity 0.3s ease;`;
        panel.innerHTML = `<div style="font-weight:normal; color:#94a3b8; padding-bottom:6px; font-size:12px; display:flex; align-items:center; gap:6px; opacity:0.8;"><div style="width:8px; height:8px; background:#3b82f6; border-radius:50%; animation: pulse 1s infinite alternate;"></div><span id="ld-floater-txt-${hash}" style="font-weight:bold;">图片生成中...</span></div><div style="font-size:12px; line-height:1.4; color:#94a3b8; overflow-y:auto; max-height:80px; flex:1; position:relative; opacity:0.7;">${prompt}</div><style>@keyframes pulse { from { opacity: 0.3; transform:scale(0.8); } to { opacity: 1; transform:scale(1.2); } }</style>`;
        layer.appendChild(panel); return { elem: panel, prompt: prompt, msgId: msgId, isTracking: true };
    }
    function updateAllTrackingPositions() {
        const { layer } = getOverlayLayer(); if (!layer) return; const layerRect = layer.getBoundingClientRect();
        Object.keys(trackers).forEach(hash => { const state = trackers[hash]; if (!state.isTracking) return; const $mes = retrieveDisplayedMessage(state.msgId); if (!$mes || $mes.length === 0) return; const textRect = fastFindTextRect($mes, state.prompt); if (textRect && textRect.height > 0) { state.elem.style.opacity = '1'; state.elem.style.top = (textRect.bottom - layerRect.top + 6) + 'px'; const panelWidth = state.elem.offsetWidth || 300; const centerLeft = (layerRect.width - panelWidth) / 2; state.elem.style.left = Math.max(0, centerLeft) + 'px'; } else { state.elem.style.opacity = '0'; } });
    }

    function applyImgStyle($elem) { $elem.css({ 'max-width': '100%', 'border-radius': '12px', 'box-shadow': '0 4px 15px rgba(0,0,0,0.1)', 'border': 'none', 'margin-top': '12px', 'object-fit': 'contain', 'display': 'block', 'background': 'transparent', 'padding': '0', 'cursor': 'pointer', '-webkit-touch-callout': 'none' }); }
    function hydrateDisplayedMessageSync(msgId) {
        const $mes = retrieveDisplayedMessage(msgId); if (!$mes || $mes.length === 0) return;
        $mes.find('img[data-ld-hash]').each(function () { const hash = $(this).attr('data-ld-hash'); const currentSrc = $(this).attr('src'); if (!currentSrc || !currentSrc.startsWith('blob:')) { if (BlobUrlCache[hash]) { $(this).attr('src', BlobUrlCache[hash]); applyImgStyle($(this)); } else { getBlobUrl(hash).then(url => { if (url && (!$(this).attr('src') || !$(this).attr('src').startsWith('blob:'))) { $(this).attr('src', url); applyImgStyle($(this)); } }); } } else { applyImgStyle($(this)); } });
    }
    function runHydrationPulse(msgId) {
        const pulse = () => { try { if (msgId === 'all') { const lastId = getLastMessageId(); const start = Math.max(0, lastId - 40); const msgs = getChatMessages(`${start}-${lastId}`); if (msgs) for (let m of msgs) hydrateDisplayedMessageSync(m.message_id); } else { hydrateDisplayedMessageSync(msgId); } } catch (e) { } };
        pulse(); setTimeout(pulse, 100); setTimeout(pulse, 300); setTimeout(pulse, 800); setTimeout(pulse, 1500);
    }

    async function processAndHydrateMessage(msgId) {
        const msgs = getChatMessages(msgId); if (!msgs || !msgs[0]) return;
        let isChanged = false, newMessage = msgs[0].message; const chatVars = getVariables({ type: 'chat' });
        const matches = matchAllLocalImg(newMessage);
        for (let i = matches.length - 1; i >= 0; i--) {
            const m = matches[i];
            const shortPrompt = m.inner.trim(); const hash = hashPrompt(shortPrompt);
            if (chatVars[`LD_STATE_${hash}`] === 'DONE') {
                isChanged = true; if (trackers[hash]) { trackers[hash].elem.remove(); delete trackers[hash]; }
                const replacement = `\n\n<img data-ld-hash="${hash}" data-ld-prompt="${encodeURIComponent(shortPrompt)}" src="" style="display:none;" alt="Generated Image" />\n\n`;
                newMessage = newMessage.slice(0, m.start) + replacement + newMessage.slice(m.end);
            }
        }
        if (isChanged) { try { await setChatMessages([{ message_id: msgId, message: newMessage }]); } catch (e) { } }
        runHydrationPulse(msgId);
    }


    // ==========================================
    // 🥕 模块 2：LoRA 热插拔（仅萝卜梦适配可用）
    //   对应 TurnipDream 3.1.37 / code 117 的 LoRA 控制面：
    //     GET  http://127.0.0.1:8082/loras  → 能力探测 + 已导入列表 + 当前选择
    //     POST http://127.0.0.1:8082/lora   → 提交选择，返回打包好的 lora_dir / lora_strength
    //   实测要点（来自交接文档 3.1.37）：
    //     · 8082 只在后端进程活着时存在，旧版客户端直接 TypeError → 当「不支持」处理
    //     · 首次某组合要真机打包 2–5 s（多 LoRA 更久），同组合命中缓存毫秒级
    //     · 所以：打包只在用户点「应用」或进面板后台补包时做，出图只吃缓存；
    //       缓存失效的那一张降级为无 LoRA 出图并提示一次，绝不让聊天队列卡在 I/O 上
    // ==========================================
    const LORA_API = 'http://127.0.0.1:8082';
    const LORA_CACHE = 'LD_LoraCache';

    // 探测结果；probed=false 表示还没探过 / 探失败（旧版客户端、后端没起、模型不支持）
    let loraState = { probed: false, api: 0, app: '', version: '', model: '', supported: false, loras: [], selection: '' };
    let loraPacking = false;
    let loraAutoPackAt = 0, loraAutoPackKey = '';   // 后台补包冷却，避免每次切标签页都重试
    const loraWarned = new Set();

    function loraToast(msg, type = 'info') {
        try { if (typeof toastr !== 'undefined' && toastr[type]) toastr[type](msg); else console.log('[LoRA] ' + msg); }
        catch (e) { console.log('[LoRA] ' + msg); }
    }
    // 同一条提醒只弹一次，避免聊天里每张图都刷屏
    function loraToastOnce(key, msg, type = 'warning') {
        if (loraWarned.has(key)) return;
        loraWarned.add(key); loraToast(msg, type);
    }

    function loraEscape(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
    }

    // 选择字符串 ↔ [{name, strength}]，格式与 app 的 lora_selection.txt 一致：名字@强度，逗号分隔
    function loraParseSelection(sel) {
        if (!sel || typeof sel !== 'string') return [];
        const out = [];
        sel.split(',').forEach(part => {
            const chunk = part.trim(); if (!chunk) return;
            const at = chunk.lastIndexOf('@');
            if (at <= 0) { out.push({ name: chunk, strength: 1.0 }); return; }
            const name = chunk.slice(0, at).trim(); if (!name) return;
            let strength = parseFloat(chunk.slice(at + 1));
            if (!isFinite(strength)) strength = 1.0;
            out.push({ name, strength: Math.min(2, Math.max(0, strength)) });
        });
        return out;
    }
    function loraFormatSelection(list) {
        return (list || []).filter(x => x && x.name)
            .map(x => `${x.name}@${Math.round((Number(x.strength) || 1.0) * 100) / 100}`).join(', ');
    }
    function loraSelectionEqual(a, b) {
        const A = loraParseSelection(a), B = loraParseSelection(b);
        if (A.length !== B.length) return false;
        return A.every((x, i) => x.name === B[i].name && Math.abs(x.strength - B[i].strength) < 1e-6);
    }

    // 打包结果缓存。目录只在「当前后端进程 + 当前模型」下有效，所以把模型 id 一起存，换模型即作废
    function getLoraCache() {
        try { const raw = localStorage.getItem(LORA_CACHE); const o = raw ? JSON.parse(raw) : null; return (o && typeof o === 'object') ? o : null; }
        catch (e) { return null; }
    }
    function setLoraCache(obj) {
        try { if (!obj || !obj.dir) localStorage.removeItem(LORA_CACHE); else localStorage.setItem(LORA_CACHE, JSON.stringify(obj)); }
        catch (e) { }
    }

    async function loraFetchJson(path, init, timeoutMs) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeoutMs || 4000);
        try {
            const res = await fetch(`${LORA_API}${path}`, Object.assign({ cache: 'no-store', signal: controller.signal }, init || {}));
            const data = await res.json().catch(() => ({}));
            return { ok: res.ok, status: res.status, data };
        } finally { clearTimeout(timer); }
    }

    // 能力探测：返回 state；null = 这台机器 / 这个客户端版本没有 LoRA 控制面
    async function loraProbe() {
        let r;
        try { r = await loraFetchJson('/loras', null, 3500); }
        catch (e) { return null; }                    // 旧版客户端 / 后端没起 / 超时
        if (!r.ok || !r.data || r.data.app !== 'localdream' || !r.data.api) return null;
        loraState = {
            probed: true, api: r.data.api, app: r.data.app, version: r.data.version || '',
            model: r.data.model || '', supported: !!r.data.supported,
            loras: Array.isArray(r.data.loras) ? r.data.loras : [], selection: r.data.selection || ''
        };
        return loraState;
    }

    // 提交选择（空数组 = 清空，让模型回到不带 LoRA）；失败抛错，message 取自后端
    async function loraPack(list) {
        const body = Array.isArray(list)
            ? { loras: list.filter(x => x && x.name).map(x => ({ name: x.name, strength: Number(x.strength) || 1.0 })) }
            : { selection: String(list || '') };
        const r = await loraFetchJson('/lora', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }, 60000);
        if (!r.ok) throw new Error((r.data && r.data.error) || `LoRA API ${r.status}`);
        return r.data;
    }

    // 出图前调用：只读缓存，绝不触发打包（首次打包会阻塞整个队列）
    function resolveLoraForRequest(config) {
        if (!config || !config.lora_enabled) return null;
        const selection = String(config.lora_selection || '').trim();
        if (!selection) return null;
        const cache = getLoraCache();
        if (!cache || !cache.dir) {
            loraToastOnce('not-packed', '🥕 已开启 LoRA 但还没打包：请回设置页点「应用选择」', 'warning');
            return null;
        }
        if (cache.model && loraState.model && cache.model !== loraState.model) {
            setLoraCache(null);
            loraToastOnce('model-changed', '🥕 后端已换模型，旧 LoRA 打包失效：本张先无 LoRA 出图，请回设置页点「应用选择」', 'warning');
            return null;
        }
        if (!loraSelectionEqual(cache.selection || '', selection)) {
            loraToastOnce('selection-changed', '🥕 当前 LoRA 选择还没打包：本张先无 LoRA 出图，请回设置页点「应用选择」', 'warning');
            return null;
        }
        return { dir: cache.dir, strength: Number(cache.strength) || 1.0 };
    }

    // ==========================================
    // ⚔️ 模块 3：生图队列与润色发包底核
    // ==========================================
    const generateQueue = [];
    function rgbBase64ToBlob(base64Raw, w, h) { return new Promise((resolve) => { const binary = atob(base64Raw); const rgbBytes = new Uint8Array(binary.length); for (let i = 0; i < binary.length; i++) rgbBytes[i] = binary.charCodeAt(i); const canvas = document.createElement('canvas'); canvas.width = w; canvas.height = h; const ctx = canvas.getContext('2d', { willReadFrequently: true }); const imgData = ctx.createImageData(w, h); for (let i = 0; i < w * h; i++) { imgData.data[i * 4] = rgbBytes[i * 3]; imgData.data[i * 4 + 1] = rgbBytes[i * 3 + 1]; imgData.data[i * 4 + 2] = rgbBytes[i * 3 + 2]; imgData.data[i * 4 + 3] = 255; } ctx.putImageData(imgData, 0, 0); canvas.toBlob(blob => resolve(blob), 'image/jpeg', 0.9); }); }

    function applyResolutionToPayload(payload, config) {
        const mode = config.resolution_mode || "size";
        const custom = (config.custom_resolution || "").trim();
        if (mode === "aspect") {
            payload.aspect_ratio = config.aspect_ratio || "1:1";
        } else if (mode === "custom" && custom) {
            const norm = custom.replace(/[：]/g, ':').replace(/[*×Xx]/g, 'x').trim();
            if (norm.includes(':')) {
                const m = norm.match(/^(\d+)\s*:\s*(\d+)$/);
                if (m) { payload.aspect_ratio = `${m[1]}:${m[2]}`; }
                else { payload.size = 512; }
            } else {
                const m = norm.match(/^(\d+)\s*x\s*(\d+)$/i);
                if (m) { payload.width = Number(m[1]); payload.height = Number(m[2]); }
                else if (/^\d+$/.test(norm)) { payload.size = Number(norm); }
                else { payload.size = 512; }
            }
        } else {
            payload.size = Number(config.resolution) || 512;
        }
    }

    async function streamGenerate(payload, config) {
        const response = await fetch('http://127.0.0.1:8081/generate', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'text/event-stream' }, body: JSON.stringify(payload) });
        if (!response.ok) throw new Error(`API 响应异常: ${response.status}`);
        const reader = response.body.getReader(); const decoder = new TextDecoder('utf-8');
        let buffer = '', finalImage = null, actualSeedUsed = null, genTimeMs = null, sseError = null;
        while (true) {
            const { done, value } = await reader.read(); if (done) break;
            buffer += decoder.decode(value, { stream: true }); const lines = buffer.split('\n'); buffer = lines.pop();
            for (const line of lines) {
                if (!line.startsWith('data: ')) continue;
                const str = line.substring(6).trim(); if (!str) continue;
                let evt;
                try { evt = JSON.parse(str); } catch (e) { continue; }
                try {
                    if (evt.type === 'progress') { if (manualProgressCallback) manualProgressCallback(evt.step, evt.total_steps, false); }
                    else if (evt.type === 'complete') { finalImage = evt; actualSeedUsed = evt.seed; genTimeMs = evt.generation_time_ms; }
                    else if (evt.type === 'error') { sseError = evt.message || 'backend error'; }
                } catch (e) { console.warn('[LocalDream] SSE 事件处理异常', e); }
            }
        }
        if (!finalImage) throw new Error(sseError || "API 未返回完整数据");
        const blob = await rgbBase64ToBlob(finalImage.image, finalImage.width, finalImage.height);
        return { blob, config, actualSeedUsed, genTimeMs };
    }

    async function executeGeneration(prompt) {
        const config = getConfig(); let final_scheduler = config.scheduler_base; if (config.use_karras && final_scheduler !== 'lcm') final_scheduler += '_karras';
        const payload = { prompt: prompt, negative_prompt: config.negative_prompt, steps: Number(config.steps), cfg: Number(config.cfg), scheduler: final_scheduler, denoise_strength: Number(config.denoise_strength) / 100.0, show_diffusion_process: false };
        applyResolutionToPayload(payload, config);
        if (config.seed !== "" && !isNaN(Number(config.seed))) Object.assign(payload, { seed: Number(config.seed) });

        // 🥕 LoRA：只挂已打包好的缓存；没开 / 没选 / 未打包成功就完全不带这两个字段
        const lora = resolveLoraForRequest(config);
        if (lora && lora.dir) { payload.lora_dir = lora.dir; payload.lora_strength = lora.strength; }
        try {
            return await streamGenerate(payload, config);
        } catch (e) {
            if (!lora || !lora.dir) throw e;
            const msg = String((e && e.message) || '');
            // 只有打包目录失效（换模型 / 清缓存 / 重装）才会带这类报错：作废缓存，本张降级无 LoRA 再出一次
            if (!/lora|swap_lora|safetensors/i.test(msg)) throw e;
            setLoraCache(null);
            loraToast('🥕 LoRA 打包目录已失效，本张已自动改用无 LoRA 出图；请回设置页点「应用选择」重新打包', 'warning');
            delete payload.lora_dir; delete payload.lora_strength;
            return await streamGenerate(payload, config);
        }
    }

    async function processQueue() {
        if (isProcessing || generateQueue.length === 0) return; isProcessing = true; const task = generateQueue.shift();
        try {
            const result = await executeGeneration(task.prompt);
            await saveImageToDB(task.hash, result.blob, task.prompt, result.config, task.msgId, result.actualSeedUsed, result.genTimeMs);
            const cachedUrl = hostWindow.URL.createObjectURL(result.blob); BlobUrlCache[task.hash] = cachedUrl;
            if (task.msgId !== 'Manual') {
                insertOrAssignVariables({ [`LD_STATE_${task.hash}`]: "DONE" }, { type: 'chat' });
                if (builtin.duringGenerating() && msgIdMatchLast(task.msgId)) {
                    if (trackers[task.hash]) transformFloaterToImage(trackers[task.hash], cachedUrl);
                } else { await processAndHydrateMessage(task.msgId); }
            }
        } catch (e) {
            if (task.msgId !== 'Manual') { insertOrAssignVariables({ [`LD_STATE_${task.hash}`]: "ERROR" }, { type: 'chat' }); }
        } finally {
