    function enqueueGeneration(targetPrompt, msgId, explicitHash = null, basePrompt = null) {
        let actualPrompt = basePrompt !== null ? basePrompt : targetPrompt;
        let taskHash = explicitHash !== null ? explicitHash : hashPrompt(actualPrompt);

