    hostWindow.document.addEventListener('pointerdown', (e) => { if (fanMenu && !fanMenu.contains(e.target) && e.target !== floatingBall) { closeFanMenu(); } if (retryPanel && !retryPanel.contains(e.target)) { closeRetryPanel(); } }, { capture: true });

    function createFloatingBall() {
        const STORAGE_KEY = 'ld-fab-pos', FAB_SIZE = 44; let isDragging = false, hasMoved = false, dragStart = { x: 0, y: 0 }, dragBase = { x: 0, y: 0 }, fabHoldTimer = null;
        function clampPos(x, y) { return { x: Math.max(10, Math.min(x, hostWindow.innerWidth - FAB_SIZE - 10)), y: Math.max(10, Math.min(y, hostWindow.innerHeight - FAB_SIZE - 10)) }; }
        floatingBall = hostWindow.document.createElement('div'); floatingBall.innerHTML = '🎨';
        const raw = hostWindow.localStorage.getItem(STORAGE_KEY), pos = raw ? clampPos(JSON.parse(raw).x, JSON.parse(raw).y) : { x: hostWindow.innerWidth - 60, y: hostWindow.innerHeight - 150 };
        floatingBall.style.cssText = `position: fixed !important; top: ${pos.y}px !important; left: ${pos.x}px !important; width: ${FAB_SIZE}px !important; height: ${FAB_SIZE}px !important; line-height: ${FAB_SIZE}px !important; border-radius: 50% !important; background: rgba(15, 23, 42, 0.88) !important; border: 1px solid rgba(255, 255, 255, 0.1) !important; backdrop-filter: blur(8px) !important; cursor: grab !important; display: flex !important; align-items: center !important; justify-content: center !important; box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3) !important; color: white !important; z-index: 999998 !important; user-select: none !important; touch-action: none !important; font-size: 20px !important; -webkit-tap-highlight-color: transparent !important;`;
        floatingBall.onpointerdown = (e) => { if (e.button !== 0) return; e.preventDefault(); isDragging = false; hasMoved = false; longPressFired = false; dragStart = { x: e.clientX, y: e.clientY }; dragBase = { x: floatingBall.getBoundingClientRect().left, y: floatingBall.getBoundingClientRect().top }; floatingBall.style.cursor = 'grabbing'; fabHoldTimer = setTimeout(() => { if (!hasMoved && !longPressFired) { longPressFired = true; createFanMenu(floatingBall.getBoundingClientRect()); } fabHoldTimer = null; }, 550); const move = (em) => { const dx = em.clientX - dragStart.x, dy = em.clientY - dragStart.y; if (Math.abs(dx) > 3 || Math.abs(dy) > 3) { hasMoved = true; isDragging = true; if (fabHoldTimer) { clearTimeout(fabHoldTimer); fabHoldTimer = null; } const np = clampPos(dragBase.x + dx, dragBase.y + dy); floatingBall.style.left = np.x + 'px'; floatingBall.style.top = np.y + 'px'; } }; const up = () => { hostWindow.removeEventListener('pointermove', move); hostWindow.removeEventListener('pointerup', up); floatingBall.style.cursor = 'grab'; if (fabHoldTimer) { clearTimeout(fabHoldTimer); fabHoldTimer = null; } setTimeout(() => hasMoved = false, 100); hostWindow.localStorage.setItem(STORAGE_KEY, JSON.stringify({ x: floatingBall.getBoundingClientRect().left, y: floatingBall.getBoundingClientRect().top })); }; hostWindow.addEventListener('pointermove', move); hostWindow.addEventListener('pointerup', up); };
        floatingBall.onclick = () => { if (!hasMoved && !longPressFired && typeof createUI === 'function') { createUI(); } }; hostWindow.document.body.appendChild(floatingBall);
