    // ---------- 🥕 LoRA 面板（懒初始化，第一次切到设置页时才探测） ----------
    let loraUIReady = false;

    function loraSetStatus(text, isErr) {
        if (!uiContainer) return;
        const el = uiContainer.querySelector('#ld-lora-status'); if (!el) return;
        el.style.color = isErr ? '#ef4444' : 'var(--ld-text-dim)';
        el.innerText = text || '';
