    // 由 loraState 渲染每一行：[√] 名字 [强度滑杆 0–2] 数值
    function loraRenderRows(restoreSelection) {
        if (!uiContainer) return;
        const list = uiContainer.querySelector('#ld-lora-list'); if (!list) return;
        const map = {};
        loraParseSelection(restoreSelection).forEach(x => { map[x.name] = x.strength; });
        const loras = (loraState.loras || []).filter(x => x && x.name);
        list.innerHTML = loras.map(item => {
            const name = String(item.name);
            const on = Object.prototype.hasOwnProperty.call(map, name);
            const strength = on ? map[name] : 1.0;
            return `<div data-lora-name="${loraEscape(name)}" style="display:flex; align-items:center; gap:8px; background:var(--ld-input-bg); border:1px solid var(--ld-border); border-radius:6px; padding:6px 8px;">
                        <input type="checkbox" ${on ? 'checked' : ''} style="width:16px;height:16px;flex:0 0 auto;cursor:pointer;">
                        <span style="flex:1; min-width:0; font-size:12px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${loraEscape(name)}">${loraEscape(name)}</span>
                        <input type="range" min="0" max="2" step="0.05" value="${strength.toFixed(2)}" style="width:72px; flex:0 0 auto; cursor:pointer;">
                        <span style="font-size:11px; width:26px; text-align:right; flex:0 0 auto;">${strength.toFixed(1)}</span>
                    </div>`;
        }).join('');
        const empty = uiContainer.querySelector('#ld-lora-empty');
        if (empty) empty.style.display = loras.length ? 'none' : 'block';
        list.querySelectorAll('div[data-lora-name]').forEach(row => {
            const cb = row.querySelector('input[type="checkbox"]');
            const rng = row.querySelector('input[type="range"]');
            const val = row.querySelectorAll('span')[1];
            const paint = () => { row.style.opacity = (cb && cb.checked) ? '1' : '0.55'; };
            if (rng && val) rng.addEventListener('input', () => { val.innerText = Number(rng.value).toFixed(1); });
            if (cb) cb.addEventListener('change', paint);
            paint();
        });
        loraSyncEnableUI();
    }

    function loraCollectUIList() {
        const out = [];
        if (!uiContainer) return out;
        uiContainer.querySelectorAll('#ld-lora-list > div[data-lora-name]').forEach(row => {
            const cb = row.querySelector('input[type="checkbox"]');
            if (!cb || !cb.checked) return;
            const rng = row.querySelector('input[type="range"]');
            out.push({ name: row.dataset.loraName, strength: rng ? Number(rng.value) : 1.0 });
        });
        return out;
    }

    // 支持才显示整块；开关关掉时只变淡，不禁用，方便先看列表
    function loraSyncEnableUI() {
        if (!uiContainer) return;
        const box = uiContainer.querySelector('#ld-lora-box'); if (!box) return;
        const ok = !!(loraState.probed && loraState.supported);
        box.style.display = ok ? 'block' : 'none';
        if (!ok) return;
        const en = uiContainer.querySelector('#ld-lora-enable');
        const body = uiContainer.querySelector('#ld-lora-body');
        const model = uiContainer.querySelector('#ld-lora-model');
        const conf = getConfig();
        if (model) model.innerText = `当前模型：${loraState.model || '未知'}${loraState.version ? ' ｜ 客户端 ' + loraState.version : ''} ｜ 已导入 ${(loraState.loras || []).length} 个`;
        if (en) en.checked = !!conf.lora_enabled;
        if (body) body.style.opacity = (en && en.checked) ? '1' : '0.5';
    }

    async function loraBackgroundPack(selection) {
        if (loraPacking) return;
        loraPacking = true;
        loraSetStatus('⏳ 正在恢复 LoRA 打包缓存…（首次几秒）');
        try {
            const packed = await loraPack(loraParseSelection(selection));
            const sel = packed.selection || selection;
            setLoraCache({ selection: sel, dir: packed.lora_dir || '', strength: Number(packed.lora_strength) || 1.0, model: packed.model || loraState.model });
            saveConfig({ lora_selection: sel });
            loraWarned.clear();
            loraRenderRows(sel);
            loraSetStatus(packed.lora_dir ? `✅ 已就绪：${sel}` : '✅ 当前为无 LoRA');
        } catch (e) {
            const msg = String((e && e.message) || '打包失败');
            if (/unknown lora/i.test(msg)) {
                saveConfig({ lora_selection: '' }); setLoraCache(null); loraRenderRows('');
                loraSetStatus('⚠️ app 里已找不到该 LoRA，已清空选择', true);
            } else {
                loraSetStatus('⚠️ ' + msg + '（本张会先无 LoRA 出图）', true);
            }
        } finally { loraPacking = false; }
    }

    // 探测 + 渲染。silent=true 时不弹「不支持」提示（切标签页会反复触发）
    async function refreshLoraList(opts) {
        const silent = !!(opts && opts.silent);
        if (!uiContainer || !uiContainer.querySelector('#ld-lora-box')) return;
        const st = await loraProbe();
        if (!st || !st.supported) {
            loraSyncEnableUI();
            if (!silent) loraToastOnce('unsupported', '🥕 当前模型不是萝卜梦 Swap 包（或客户端 < 3.1.37），LoRA 不可用', 'info');
            return;
        }
        const conf = getConfig();
        const restore = String(conf.lora_selection || '').trim() || st.selection || '';
        loraRenderRows(restore);
        loraSetStatus(`已就绪：${st.loras.length} 个 LoRA 可选`);
        // 选择还在但缓存对不上（刷新页面 / 换模型）→ 后台补包一次，不阻塞出图
        const cache = getLoraCache();
        const need = !!(restore && conf.lora_enabled && (!cache || !cache.dir || cache.model !== st.model || !loraSelectionEqual(cache.selection, restore)));
        const cooled = (Date.now() - loraAutoPackAt > 60000) || loraAutoPackKey !== restore;
        if (need && !loraPacking && cooled) { loraAutoPackAt = Date.now(); loraAutoPackKey = restore; loraBackgroundPack(restore); }
    }

    async function applyLoraFromUI() {
        if (!uiContainer) return;
        const btn = uiContainer.querySelector('#ld-lora-apply');
        const list = loraCollectUIList();
        const selection = loraFormatSelection(list);
        if (btn) { btn.disabled = true; btn.innerText = '⏳ 正在打包 LoRA…（首次几秒）'; }
        loraPacking = true;
        loraSetStatus('⏳ 正在打包 LoRA…（多 LoRA 或首次会久一点）');
        try {
            const packed = await loraPack(list);
            const sel = packed.selection || selection;
            setLoraCache({ selection: sel, dir: packed.lora_dir || '', strength: Number(packed.lora_strength) || 1.0, model: packed.model || loraState.model });
            saveConfig({ lora_selection: sel });
            loraWarned.clear();
            const switchedOn = !!getConfig().lora_enabled;
            loraSetStatus(sel ? `✅ 已应用：${sel}${switchedOn ? '' : '（⚠️ 总开关没开，出图仍不会用 LoRA）'}` : '✅ 已清空 LoRA（模型回到无 LoRA）');
            loraToast(sel ? `🥕 LoRA 已应用：${sel}` : '🥕 已清空 LoRA', 'success');
        } catch (e) {
            const msg = String((e && e.message) || '打包失败');
            loraSetStatus('❌ ' + msg, true);
            loraToast('🥕 LoRA 打包失败：' + msg, 'error');
        } finally {
            loraPacking = false;
            if (btn) { btn.disabled = false; btn.innerText = '✅ 应用选择（打包）'; }
        }
    }

    // 每次切到设置页都会走到这里：首次绑事件，之后只重新探测
    function initLoraUI() {
        if (!uiContainer || !uiContainer.querySelector('#ld-lora-box')) return;
        if (!loraUIReady) {
            const en = uiContainer.querySelector('#ld-lora-enable');
            const refresh = uiContainer.querySelector('#ld-lora-refresh');
            const apply = uiContainer.querySelector('#ld-lora-apply');
            if (en) en.addEventListener('change', () => {
                const conf = saveConfig({ lora_enabled: !!en.checked });
                loraSyncEnableUI();
                const sel = String(conf.lora_selection || '').trim();
                const cache = getLoraCache();
                if (conf.lora_enabled && sel && (!cache || !cache.dir || !loraSelectionEqual(cache.selection, sel))) loraBackgroundPack(sel);
            });
            if (refresh) refresh.onclick = () => refreshLoraList();
            if (apply) apply.onclick = applyLoraFromUI;
            loraUIReady = true;
        }
        loraSyncEnableUI();
        refreshLoraList({ silent: true });
    }

    function createUI() {
        const cConf = getConfig();
        if (uiContainer) {
            uiContainer.style.display = 'flex'; applyThemeToUI(cConf.theme);
