    function renderMainModalUI() {
        const theme = AppState.globalCfg.uiTheme === 'dark' ? 'pg-theme-dark' : 'pg-theme-light'; const isSettings = AppState.activeIndex === -1; const curGen = !isSettings ? AppState.generators[AppState.activeIndex] : null;

        let navHtml = AppState.generators.map((g, i) => `
            <div class="pg-nav-item ${AppState.activeIndex === i ? 'active' : ''}" data-idx="${i}">
                <span style="font-size:15px;">${g.icon}</span>
                <span style="flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; margin:0 10px; font-size:13px; font-weight:${AppState.activeIndex===i?'bold':'normal'}; color:${AppState.activeIndex===i?'var(--pg-primary)':'var(--pg-text)'};" title="${g.name}">${g.name}</span>
                <div class="pg-nav-indicator ${g.isActive ? 'is-active' : ''}" data-indicator-idx="${i}" title="${g.isActive ? '当前活跃的截取模板' : '点击激活该模板'}"></div>
