        navHtml += `<div class="pg-nav-item ${isSettings ? 'active' : ''}" data-idx="-1"><span style="margin-left:2px;">⚙️</span> <span style="flex:1; margin:0 10px; font-size:13px; font-weight:${isSettings?'bold':'normal'}; color:${isSettings?'var(--pg-primary)':'var(--pg-text)'};">API 与底层偏好</span></div>`;

        let contentHtml = isSettings ? renderSettingsHTMLPG() : renderGeneratorHTMLPG(curGen, AppState.activeIndex);

        let container = null, scrollArea = null; let savedScrollTop = 0;
        if (mainModal) { container = mainModal.querySelector('.pg-container'); scrollArea = mainModal.querySelector('#pg-content-area'); if(scrollArea) savedScrollTop = scrollArea.scrollTop; }

        if (!container) {
            mainModal.innerHTML = `<div class="pg-container ${theme}"><div class="pg-header"><div>🧠 提示词智能润色系统 <span style="font-size:12px;opacity:0.6;font-weight:normal;margin-left:8px;">v7.6 内核</span></div><div class="pg-close" id="pg-close-main">×</div></div><div class="pg-body"><div class="pg-sidebar">${navHtml}</div><div class="pg-content pg-scroll" id="pg-content-area">${contentHtml}</div></div></div>`;
            mainModal.querySelector('#pg-close-main').onclick = () => {
                 if (AppState.activeIndex >= 0) saveCurrentFormPG(AppState.activeIndex);
                 mainModal.style.display = 'none';
            };
        } else {
            container.className = `pg-container ${theme}`;
            mainModal.querySelector('.pg-sidebar').innerHTML = navHtml;
            mainModal.querySelector('#pg-content-area').innerHTML = contentHtml;
        }

        let dd = mainModal.querySelector('#pg-dropdown-menu');
        if (!dd && mainModal.querySelector('.pg-container')) {
            dd = hostWindow.document.createElement('div');
            dd.id = 'pg-dropdown-menu'; dd.className = 'pg-dropdown'; dd.style.display = 'none';
            dd.innerHTML = `<div class="pg-dropdown-item" id="pg-dd-edit">✏️ 重命名该模板</div><div class="pg-dropdown-item" id="pg-dd-export">📤 独立导出此模板</div><div class="pg-dropdown-item" id="pg-dd-import" style="color:var(--pg-primary);">📥 导入并覆盖当前模板</div>`;
            mainModal.querySelector('.pg-container').appendChild(dd);
            bindDropdownEventsPG(dd);
        }

        mainModal.querySelectorAll('.pg-nav-item').forEach(el => el.onclick = (e) => {
            if (e.target.closest('.pg-btn-more') || e.target.closest('.pg-nav-indicator')) return;
            const newIdx = parseInt(el.getAttribute('data-idx'));
            if (AppState.activeIndex !== newIdx) {
                if (AppState.activeIndex >= 0) saveCurrentFormPG(AppState.activeIndex);
                AppState.activeIndex = newIdx; renderMainModalUI();
            }
        });

        mainModal.querySelectorAll('.pg-nav-indicator').forEach(ind => ind.onclick = (e) => {
            const i = parseInt(e.target.getAttribute('data-indicator-idx'));
