    function bindDropdownEventsPG(dd) {
        const getIdx = () => parseInt(dd.getAttribute('data-target-idx'));
        dd.querySelector('#pg-dd-edit').onclick = () => {
            dd.style.display = 'none'; const i = getIdx();
            const newName = prompt("请输入模板名称:", AppState.generators[i].name);
            if (newName && newName.trim()) { AppState.generators[i].name = newName.trim(); saveTemplatesPG(); renderMainModalUI(); }
        };
        dd.querySelector('#pg-dd-export').onclick = () => {
            dd.style.display = 'none'; const i = getIdx(); const gen = AppState.generators[i];
            const exportData = { templateName: gen.name, sys: gen.sys, anchorText: gen.anchorText, blocks: gen.blocks.map(b => (b.type === 'text' ? { type: b.type, content: b.content } : { type: b.type })) };
            const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `prompt-polish-template-${gen.name}.json`; a.click(); URL.revokeObjectURL(url);
        };
        dd.querySelector('#pg-dd-import').onclick = () => {
            dd.style.display = 'none'; const i = getIdx(); const input = document.createElement('input'); input.type = 'file'; input.accept = '.json';
            input.onchange = ev => {
                const file = ev.target.files[0]; if(!file) return; const reader = new FileReader();
                reader.onload = e => {
                    try {
                        const data = JSON.parse(e.target.result);
                        if(data.sys === undefined || !Array.isArray(data.blocks)) throw new Error("缺少卡片结构组，文件可能已损坏");
                        if(confirm(`📦 模板解析成功！\n\n📌 来源名: ${data.templateName || '未命名'}\n🎯 覆盖至: ${AppState.generators[i].name}\n📝 包含卡片: ${data.blocks.length} 张\n\n注意：此操作将覆盖您的文本内容和排序，但原本的抓取深度及世界书勾选将被安全保留。\n\n确认导入并覆盖吗？`)){
                            const gen = AppState.generators[i]; gen.sys = data.sys || ""; gen.anchorText = data.anchorText || "";
                            const requiredSpecials = ['worldbook', 'variables', 'history']; const newBlocks = [];
                            for(let b of data.blocks) {
                                if (b.type === 'text') newBlocks.push({ type: 'text', content: b.content || '' });
                                else if (requiredSpecials.includes(b.type)) { newBlocks.push({ type: b.type }); requiredSpecials.splice(requiredSpecials.indexOf(b.type), 1); }
                            }
                            requiredSpecials.forEach(type => newBlocks.push({ type }));
                            if(newBlocks.filter(b=>b.type==='text').length === 0) newBlocks.push({ type:'text', content:'' });
                            gen.blocks = newBlocks; saveTemplatesPG(); renderMainModalUI(); alert("✨ 模板结构导入成功！");
                        }
                    } catch(err) { alert("❌ JSON 解析或导入失败: " + err.message); }
                }; reader.readAsText(file);
            }; input.click();
        };
    }

