            <div class="pg-block-header">📡 模型 API 接入</div><div class="pg-block-body" style="border-radius:0 0 10px 10px;"> <div class="pg-twocol"> <div><label>请求代理源</label><select id="cfg-type" class="pg-input"><option value="openai" ${api.apiType==='openai'?'selected':''}>OpenAI 兼容</option><option value="claude" ${api.apiType==='claude'?'selected':''}>Claude</option></select></div> <div><label>模型选择</label> <div style="display:flex; gap:8px;"> <input id="cfg-model" class="pg-input" style="flex:1; margin:0;" value="${api.model}"> <button id="btn-fetch-models" class="pg-btn" style="padding:0 12px; margin:0;">🔄</button> </div> <select id="cfg-model-select" class="pg-input" style="display:none; margin-top:8px; margin-bottom:0;"></select> </div> </div> <label style="display:block; margin-top:10px;">API 地址 (如含 /v1/ 则保留)</label><input id="cfg-url" class="pg-input" value="${api.apiUrl}"> <label>API 密钥</label><input id="cfg-key" type="password" class="pg-input" value="${api.apiKey}"> <div class="pg-twocol" style="margin-bottom:10px;"> <div><label>Temperature</label><input id="cfg-temp" type="number" step="0.1" class="pg-input" value="${api.temperature}"></div> <div><label>Max Tokens</label><input id="cfg-max" type="number" class="pg-input" value="${api.maxTokens}"></div> </div> <button class="pg-btn" id="cfg-save" style="width:100%;">💾 保存设置</button> </div>
        `;
