            AppState.apiSettings = { apiType: root.querySelector('#cfg-type').value, apiUrl: root.querySelector('#cfg-url').value, apiKey: root.querySelector('#cfg-key').value, model: root.querySelector('#cfg-model').value, temperature: parseFloat(root.querySelector('#cfg-temp').value), maxTokens: parseInt(root.querySelector('#cfg-max').value) }; saveStoragePG(STORAGE_KEY_API, AppState.apiSettings); logPG('设置已完整保存', 'success'); renderMainModalUI();
