            else if (isVar) { innerContent = `<p style="font-size:13px; opacity:0.8; margin-top:0;">捕获指定深度的局部变量并还原为文本状态。</p><div style="display:flex; align-items:center; gap:8px; background:var(--pg-bg); padding:10px; border-radius:8px; border:1px solid var(--pg-border);"> <b>目标深度 (倒数AI楼层)</b> <input type="number" id="gen-var" class="pg-input-inline" style="width:60px; margin:0;" value="${gen.varDepth}" min="0"> </div>`; }
