    function renderWbAccordionBox(query = '') {
        const area = mainModal.querySelector('#wb-accordion-area'); if (!area) return;
        let charData = AppState.savedWbSelections[AppState.curCharName] || {}; let wbsToShow = new Set();
        if (AppState.activeRoleWorldbook) wbsToShow.add(AppState.activeRoleWorldbook); Object.keys(charData).forEach(k => { if (charData[k].enabled || (charData[k].entries && charData[k].entries.length > 0)) wbsToShow.add(k); });
        if (AppState.wbViewShowAll) AppState.allWbNames.forEach(n => wbsToShow.add(n));
        let sortedWbs = Array.from(wbsToShow).sort((a,b) => { let aE = charData[a]?.enabled ? 1 : 0; let bE = charData[b]?.enabled ? 1 : 0; if (aE !== bE) return bE - aE; return a.localeCompare(b); });
        if (sortedWbs.length === 0) { area.innerHTML = '<div style="opacity:0.6; text-align:center; margin-top:40px;">节点库为空</div>'; return; }
        let html = '';
        if (query.trim()) {
            const q = query.toLowerCase(); let hitCount = 0;
            sortedWbs.forEach(wbName => { const cnf = charData[wbName]; const isEnabled = cnf ? cnf.enabled : false; if (!isEnabled) return;
                const srcArr = AppState.wbCacheMap[wbName] || [];
