    async function buildPromptPG(idx, mockSliceText, excludeMsgId = null) {
        const gen = AppState.generators[idx]; const gb = AppState.globalCfg; let pParts = [];
        for (let b of gen.blocks) {
            if (b.type === 'text') {
                if (b.content && b.content.trim()) pParts.push(b.content.trim());
            }
            if (b.type === 'worldbook') {
                let contextParts = []; let charData = AppState.savedWbSelections[AppState.curCharName] || {};
                for (let wb of Object.keys(charData)) {
                    if (charData[wb].enabled && charData[wb].entries && charData[wb].entries.length > 0) {
                        await ensureWbFetched(wb); const activeEntries = (AppState.wbCacheMap[wb]||[]).filter(e => charData[wb].entries.includes(e.name));
                        if (activeEntries.length > 0) { let wbLines = activeEntries.map(e => `[包含设定:${e.name}]\n${applyExclusions(e.content)}`).join('\n\n'); contextParts.push(wbLines); }
                    }
                }
                if (contextParts.length > 0) pParts.push(`<character_and_world_lore>\n${contextParts.join('\n\n')}\n</character_and_world_lore>`);
            }
            if (b.type === 'history') {
                if ((gen.historyCount > 0 || (gen.historyExtra && gen.historyExtra.trim() !== '')) && typeof getChatMessages === 'function' && typeof getLastMessageId === 'function') {
                    try {
                        let targetIds = new Set(); const lastId = getLastMessageId();
                        if (gen.historyExtra && gen.historyExtra.trim() !== '') { gen.historyExtra.split(/[,，]/).forEach(numStr => { const num = parseInt(numStr.trim(), 10); if (!isNaN(num) && num >= 0 && num <= lastId) { targetIds.add(num); } }); }
                        let collectedCount = 0; for (let id = lastId; id >= 0 && collectedCount < gen.historyCount; id--) { const msgs = getChatMessages(id); if (msgs && msgs.length > 0 && !msgs[0].is_hidden) { targetIds.add(id); collectedCount++; } }
                        let sortedIds = Array.from(targetIds).sort((a, b) => a - b); let historyTexts = [];
                        for (let i = 0; i < sortedIds.length; i++) {
                            const id = sortedIds[i];
                            if (excludeMsgId !== null && id === excludeMsgId) continue;
                            const msgs = getChatMessages(id);
                            if (msgs && msgs.length > 0) {
                                const m = msgs[0]; if (m.is_hidden) continue; const roleName = m.role === 'user' ? '用户' : (m.role === 'assistant' ? '角色' : '系统'); let rawText = m.message;
                                if (m.role === 'assistant' && gb.charExtractTag) { const reg = new RegExp(`<${gb.charExtractTag}>([\\s\\S]*?)<\\/${gb.charExtractTag}>`, 'i'); const match = rawText.match(reg); if (match) rawText = match[1]; }
                                else if (m.role === 'user' && gb.userExtractTag) { const reg = new RegExp(`<${gb.userExtractTag}>([\\s\\S]*?)<\\/${gb.userExtractTag}>`, 'i'); const match = rawText.match(reg); if (match) rawText = match[1]; }
                                let cleanText = applyExclusions(rawText).trim(); historyTexts.push(`[楼层 ${id}] ${roleName}: ${cleanText}`);
                            }
                        }
                        if (historyTexts.length > 0) pParts.push(`<recent_story_context>\n${historyTexts.join('\n\n')}\n</recent_story_context>`);
                    } catch (e) { console.error("历史抓取异常", e); }
                }
            }
            if (b.type === 'variables') {
                if (gen.varDepth > 0 && typeof getChatMessages === 'function' && typeof getVariables === 'function') {
                    try {
                        let aiMsgCount = 0; let targetMsgId = -1; const lastId = getLastMessageId();
                        for (let id = lastId; id >= 0; id--) { const msgs = getChatMessages(id); if (msgs && msgs.length > 0 && msgs[0].role === 'assistant' && !msgs[0].is_hidden) { aiMsgCount++; if (aiMsgCount === gen.varDepth) { targetMsgId = id; break; } } }
                        if (targetMsgId >= 0) {
                            let floorVars = {}; try { floorVars = getVariables({type:'message', message_id: targetMsgId}) || {}; } catch(e){}
                            const cleanedObj = getCleanedVariables(floorVars);
                            if (cleanedObj && Object.keys(cleanedObj).length > 0) { const varText = JSON.stringify(cleanedObj, null, 2); pParts.push(`<character_state_variables>\n[来自于对话记录的动态状态]\n${varText}\n</character_state_variables>`); }
                        }
                    } catch (e) { console.error("变量追踪抓取异常", e); }
                }
            }
        }
        if (gen.anchorText) {
            if (mockSliceText) {
                pParts.push(`<polishing_directive>\n${gen.anchorText}\n\n--- [最新截取动态流] ---\n${mockSliceText}\n----------------------\n</polishing_directive>`);
            } else {
                pParts.push(`<polishing_directive>\n${gen.anchorText}\n</polishing_directive>`);
            }
        }
        return pParts.join('\n\n');
    }

